    /// <summary>
    /// Increases a bid for an auction gift without changing gift text and receiver
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> IncreaseGiftAuctionBidAsync(long giftId = default, long starCount = default)
    {

           using var activity =  StartCallActivity("IncreaseGiftAuctionBidAsync", typeof(IncreaseGiftAuctionBid).FullName ?? "IncreaseGiftAuctionBidAsync");

           try
           {
             return client.IncreaseGiftAuctionBidAsync(giftId, starCount);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
